import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.2Gs1zKBA.js";const p=JSON.parse('{"title":"集成能力与边界","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/index.md","filePath":"integrations/index.md","lastUpdated":1793694501000}'),o={name:"integrations/index.md"};function n(h,t,i,l,s,c){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="集成能力与边界" tabindex="-1">集成能力与边界 <a class="header-anchor" href="#集成能力与边界" aria-label="Permalink to &quot;集成能力与边界&quot;">​</a></h1><p>集成层负责把规划器、遥操作器或数据采集系统连接到 Onero A1；核心 SDK 负责模型、状态、运动和设备接口。集成项目通常还有自己的坐标系、生命周期和异常处理，不应把外部项目的“规划成功”直接等同于“真机执行安全”。</p><table tabindex="0"><thead><tr><th>集成</th><th>说明</th><th>所在位置</th></tr></thead><tbody><tr><td>ROS 2</td><td>关节状态、服务和轨迹接口示例</td><td>SDK 示例或独立 ROS 2 包</td></tr><tr><td><a href="/onerobot-A1/use-cases/moveit2">MoveIt 2</a></td><td>单臂、双臂运动规划与夹爪控制</td><td>SDK 的 moveit2 适配目录</td></tr><tr><td><a href="/onerobot-A1/use-cases/lerobot">LeRobot</a></td><td>双臂主从遥操作、数据采集与策略部署</td><td>独立项目 <a href="https://github.com/switchbot-rd/Onero_A1_Lerobot" target="_blank" rel="noreferrer">Onero_A1_Lerobot</a></td></tr><tr><td>BEAVR</td><td>Onero A1 适配器</td><td>SDK 的 BEAVR 适配目录</td></tr><tr><td>python-can</td><td>可选 CAN 传输后端</td><td><code>onero-sdk[python-can]</code></td></tr></tbody></table><p>这些集成并非都包含在核心 <code>onero-sdk</code> 安装中。使用前应确认对应包、版本和运行环境。</p><h2 id="选择集成方式" tabindex="-1">选择集成方式 <a class="header-anchor" href="#选择集成方式" aria-label="Permalink to &quot;选择集成方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>优先选择</th><th>需要额外确认</th></tr></thead><tbody><tr><td>规划、碰撞检查和复杂场景</td><td>MoveIt 2</td><td>ROS 2 版本、规划场景、执行开关</td></tr><tr><td>主从遥操作与数据采集</td><td>LeRobot</td><td>主从映射、数据格式、录制退出流程</td></tr><tr><td>头显或 VR 遥操作</td><td>BEAVR</td><td>网络延迟、启动 gate、双臂停止策略</td></tr><tr><td>简单状态读取或动作脚本</td><td><code>onero-sdk</code></td><td>CAN、安装方向、TCP 和负载</td></tr><tr><td>自定义控制循环</td><td><code>servoj</code>/<code>servop</code>/速度接口</td><td>控制频率、超时和受控停止</td></tr></tbody></table><h2 id="集成边界" tabindex="-1">集成边界 <a class="header-anchor" href="#集成边界" aria-label="Permalink to &quot;集成边界&quot;">​</a></h2><ul><li>规划器通常只知道模型和场景，不一定知道现场的真实线缆、工具或临时障碍物。</li><li>遥操作器可以提供目标，但不能替代机械臂侧的限位、停止和异常处理。</li><li>数据采集系统应保存模型、安装、工具、负载和软件版本，否则数据难以复现。</li><li>集成切换仿真与真机时，应分别验证启动、停止、失能和退出行为。</li></ul><h2 id="分层验证方法" tabindex="-1">分层验证方法 <a class="header-anchor" href="#分层验证方法" aria-label="Permalink to &quot;分层验证方法&quot;">​</a></h2><p>将问题按层拆开验证，能够避免把集成系统的故障误判为 Onero A1 或 CAN 故障：</p><table tabindex="0"><thead><tr><th>层级</th><th>应验证的内容</th><th>通过后才能进入下一层</th></tr></thead><tbody><tr><td>SDK 与后端</td><td>模型、状态读取、单臂低速运动或仿真</td><td>核心 <code>Arm</code> 接口和停止逻辑可用</td></tr><tr><td>集成适配层</td><td>坐标转换、目标映射、通道与生命周期</td><td>外部目标能被正确转换为机械臂目标</td></tr><tr><td>规划/遥操/采集系统</td><td>场景、输入设备、数据与任务流程</td><td>外部系统在仿真或 mock 环境中稳定运行</td></tr><tr><td>真机任务</td><td>环境、工具、负载、停止和恢复</td><td>经过低速、分阶段现场确认</td></tr></tbody></table><p>任何一层出现异常时，应回退到其下层的最小可复现测试，而不是同时修改规划器、CAN 配置和机械臂参数。集成项目自身的文档和版本约束同样属于部署的一部分。</p><p>完整集成案例见<a href="/onerobot-A1/use-cases/">使用案例</a>。</p>',13)])])}const _=d(o,[["render",n]]);export{p as __pageData,_ as default};
